using ApexUi::IconId;

constexpr int kOrderAfterColor = 45;  // after Apex's Picture (40)
constexpr int kOrderBeforeColor = 35; // before Apex's Picture
constexpr size_t kMaxListEntries = 256; // off / extra / runOrder entries read from the settings
constexpr size_t kMaxTweaks = 64;       // shaders with edited values read from the settings

// ---------------------------------------------------------------------------------------------- shaders
// Every ported entry point goes into Apex's ShaderCache, registered when the feature is first turned on (a new worker
// run compiles them), so a player who never uses Looks pays nothing.
struct ShaderIds
{
    std::vector<std::vector<ShaderCache::Id>> ids; // [shader][entry]
    ShaderCache::Id copy = -1;
    ShaderCache::Id hair = -1; // Sims' hair takes the picture from before a step back (Runner::KeepHair)
    bool registered = false;
} g_ids;

ShaderCache::Id AddOne(const char* tag, std::string source, const char* sourceName, const char* entry)
{
    ShaderCache::Desc d;
    d.tag = tag;
    d.source = std::move(source);
    d.sourceName = sourceName;
    d.entry = entry;
    d.target = "ps_3_0";
    d.flags = D3DCOMPILE_OPTIMIZATION_LEVEL3;
    d.priority = 2;
    return ShaderCache::Add(std::move(d));
}

void RegisterShaders()
{
    if (g_ids.registered) return;
    g_ids.registered = true;
    g_ids.copy = AddOne("Looks copy", Looks::FullSource(-1), "looks_copy.hlsl", "gs_copy");
    g_ids.hair = AddOne("Looks Sims' hair", Looks::FullSource(-2), "looks_hair.hlsl", "gs_hair");
    g_ids.ids.resize(Looks::ShaderCount());
    for (int i = 0; i < Looks::ShaderCount(); ++i)
    {
        const LooksShader& d = Looks::Shader(i);
        const std::string src = Looks::FullSource(i);
        for (const char* const* e = d.entries; *e; ++e)
            g_ids.ids[i].push_back(AddOne(*e, src, d.file, *e)); // tag = entry name (static string)
    }
}

IDirect3DPixelShader9* CreatePs(IDirect3DDevice9* dev, int shader, int entry)
{
    if (!g_ids.registered || (shader >= 0 && (shader >= (int)g_ids.ids.size() || entry < 0 || entry >= (int)g_ids.ids[shader].size()))) return nullptr;
    const ShaderCache::Id id = shader == -2 ? g_ids.hair : shader < 0 ? g_ids.copy : g_ids.ids[shader][entry];
    IDirect3DPixelShader9* ps = nullptr;
    std::string msg;
    switch (ShaderCache::CreatePixelShader(dev, id, &ps, &msg))
    {
    case ShaderCache::Result::Ok: return ps;
    case ShaderCache::Result::CompileFailed: LOG_ERROR(std::format("[Looks] shader failed to compile: {}", msg)); return nullptr;
    case ShaderCache::Result::CreateFailed: LOG_ERROR("[Looks] CreatePixelShader failed"); return nullptr;
    }
    return nullptr;
}

// ---------------------------------------------------------------------------------------------- state
struct State
{
    // settings
    std::string preset;        // "looks:<file>", "gshade:<file>"; empty = none chosen
    bool beforeColor = false;  // run before Apex's colour (Picture) instead of after
    bool onUi = false;         // also shade the game's UI, menus and loading screens (end of frame, like GShade)
    bool restConfig = false;   // run shaders where a ReShade Effect Shader Toggler .ini says (looks_rest.h)
    float mix = 1.0f;
    std::set<std::string> off; // techniques switched off here (still in the list: the .ini's or added here)
    std::map<std::string, float> hair; // technique -> how much of it Sims' hair takes, below 1 (features/sim_mask.h)
    std::set<std::string> on;  // techniques the look's file keeps listed but off (ApexOff=), switched on here
    std::set<std::string> removed; // lower-case "tech@file.fx" taken out here: listed with Restore until the look is saved
    std::map<std::string, std::vector<float>> tweaks; // technique -> 4 floats per param
    std::map<std::string, std::map<std::string, std::string>> defs; // lower-case .fx name -> definition -> value edited here
    std::vector<std::string> extra;    // "Tech@File.fx" switched on here although the .ini does not enable it
    std::vector<std::string> runOrder; // my run order ("Tech@File.fx"); empty = the .ini's order

    // runtime
    Looks::Preset ini;
    std::vector<Looks::PresetEntry> iniOrder;  // the .ini's own enabled techniques, in its order
    std::set<std::string> iniKeys;             // lower-case "tech@file.fx" of those
    std::set<std::string> iniOff;              // lower-case keys the file lists switched off (ApexOff=, written by Apex)
    std::vector<Looks::PresetEntry> order;     // the run list: the .ini's, plus added ones, in my order
    std::vector<std::vector<float>> iniValues; // per run-list entry (built-in ones)
    Looks::Runner runner;
    bool loaded = false;
    bool active = false;
    int postOrder = kOrderAfterColor;
    std::string status = "Off"; // English, for the log and the Overview
    std::string error;          // why the look could not be read (English)
    std::vector<std::string> skipped;
} g;

unsigned long long g_holdUntil = 0; // HoldBypass: the look is skipped until then (GetTickCount64)

std::string Lower(std::string s)
{
    for (char& c : s) c = (char)tolower((unsigned char)c);
    return s;
}

std::string EntryKey(const Looks::PresetEntry& e) { return e.technique + "@" + e.file; }
bool InIni(const std::string& key) { return g.iniKeys.count(Lower(key)) != 0; }
bool Runnable(size_t i) { return i < g.order.size() && g.order[i].shader >= 0; }
bool IsRemoved(size_t i) { return g.removed.count(Lower(EntryKey(g.order[i]))) != 0; }
bool OffInFile(size_t i) { return g.iniOff.count(Lower(EntryKey(g.order[i]))) != 0; }
// Off = not run: switched off (here, or in the file and not switched on here) or removed here
bool IsOff(size_t i)
{
    const std::string& t = g.order[i].technique;
    return IsRemoved(i) || (OffInFile(i) ? g.on.count(t) == 0 : g.off.count(t) != 0);
}

// Runnable shaders still in the list (removed ones not counted), or only those on
int RunnableCount(bool onlyOn)
{
    int n = 0;
    for (size_t i = 0; i < g.order.size(); ++i) n += Runnable(i) && !IsRemoved(i) && (!onlyOn || !IsOff(i));
    return n;
}

// A shader's one-line description: built-in ones are translated menu texts, a player's .fx shows its file name
const char* Describe(int shader)
{
    const LooksShader& d = Looks::Shader(shader);
    return Looks::IsUserShader(shader) ? d.description : I18n::Tr(d.description);
}

// The definitions a .fx compiles with: the look's (PreprocessorDefinitions=, then its [File.fx] section's), then the
// ones edited here
LooksDefines DefinesFor(const std::string& file)
{
    LooksDefines d = Looks::PresetDefines(g.ini, file);
    auto it = g.defs.find(Lower(file));
    if (it != g.defs.end())
        for (const auto& [name, value] : it->second)
        {
            auto at = std::find_if(d.begin(), d.end(), [&](const auto& x) { return x.first == name; });
            if (at != d.end()) at->second = value;
            else d.push_back({ name, value });
        }
    return d;
}

// The run list's player files compile with their definitions (a changed one compiles again in the background)
void PushDefines()
{
    std::map<std::string, LooksDefines> files;
    for (const auto& e : g.order)
        if (LooksDefines d = DefinesFor(e.alt.empty() ? e.file : e.alt); !d.empty()) files[Lower(e.alt.empty() ? e.file : e.alt)] = std::move(d); // the file that compiles (a stand-in: the global definitions only)
    Looks::Fx::SetDefines(files);
}

// The run list = the .ini's enabled techniques + the ones switched on here (at their TechniqueSorting place, like
// ReShade would run them), then my own order on top. Values: the .ini's section if it has one, else the .fx defaults.
void RebuildOrder()
{
    g.order = g.iniOrder;
    const std::vector<std::string> sorting = Looks::PresetSorting(g.ini);
    auto sortPos = [&](const std::string& key) {
        const std::string k = Lower(key);
        for (size_t i = 0; i < sorting.size(); ++i) if (Lower(sorting[i]) == k) return (int)i;
        return INT_MAX;
    };
    for (const std::string& x : g.extra)
    {
        const std::string lk = Lower(x);
        if (g.iniKeys.count(lk)) continue;
        bool dup = false;
        for (auto& e : g.order) dup |= Lower(EntryKey(e)) == lk;
        if (dup) continue;
        Looks::PresetEntry e;
        const size_t at = x.find('@');
        e.technique = x.substr(0, at);
        e.file = at == std::string::npos ? std::string() : x.substr(at + 1);
        e.shader = Looks::FindShader(e.technique, e.file);
        if (e.shader < 0 && !Looks::Fx::HasFile(e.file)) continue; // added here, its file gone: dropped (one not compiled yet waits)
        const int p = sortPos(x);
        size_t ins = g.order.size();
        for (size_t i = 0; i < g.order.size(); ++i)
            if (sortPos(EntryKey(g.order[i])) > p) { ins = i; break; }
        g.order.insert(g.order.begin() + (std::ptrdiff_t)ins, e);
    }
    if (!g.runOrder.empty())
    {
        // entries in my order take their place there; others stay right after the entry they followed
        struct R { int rank, missing, idx; };
        std::vector<R> r;
        int last = -1;
        for (size_t i = 0; i < g.order.size(); ++i)
        {
            const std::string k = Lower(EntryKey(g.order[i]));
            int pos = -1;
            for (size_t j = 0; j < g.runOrder.size(); ++j) if (Lower(g.runOrder[j]) == k) { pos = (int)j; break; }
            if (pos >= 0) last = pos;
            r.push_back({ pos >= 0 ? pos : last, pos >= 0 ? 0 : 1, (int)i });
        }
        std::stable_sort(r.begin(), r.end(), [](const R& a, const R& b) { return a.rank != b.rank ? a.rank < b.rank : a.missing < b.missing; });
        std::vector<Looks::PresetEntry> sorted;
        for (const R& x : r) sorted.push_back(g.order[x.idx]);
        g.order = std::move(sorted);
    }
    g.iniValues.assign(g.order.size(), {});
    std::vector<std::string> missing; // a downloaded pack's file compiles only once a look asks for it
    for (size_t i = 0; i < g.order.size(); ++i)
        // a stand-in (another file with the technique) keeps its own defaults: the look's values were set for another version
        // of the shader (MXAO 4.0.2 EX's amount 4.25 and fade to 1.0 darkened qUINT's MXAO and the sky)
        if (g.order[i].shader >= 0) g.iniValues[i] = Looks::PresetValues(g.ini, Looks::Shader(g.order[i].shader), (g.order[i].alt.empty() ? g.order[i].file : g.order[i].alt).c_str());
        else missing.push_back(g.order[i].alt.empty() ? g.order[i].file : g.order[i].alt);
    if (!missing.empty()) Looks::Fx::WantFiles(missing);
    PushDefines();
    if (g.loaded)
        g.status = std::format("{}: {} of {} shaders built in", Looks::RefName(g.preset), RunnableCount(false), g.order.size());
}

// A look entry's shader; a file found nowhere (a GShade preset's renamed file) runs from another file with the same
// technique (e.alt), when a pack of ReShade's list has one
void ResolveEntry(Looks::PresetEntry& e)
{
    e.shader = Looks::FindShader(e.technique, e.file);
    e.alt.clear();
    if (e.shader >= 0 || Looks::Fx::HasFile(e.file)) return;
    e.alt = Looks::Packs::FileForTechnique(e.file, e.technique);
    if (!e.alt.empty()) e.shader = Looks::FindShader(e.technique, e.alt);
}

void LoadPreset()
{
    g.ini = {};
    g.error.clear();
    std::string text;
    if (g.preset.empty()) g.error = "no look chosen";
    else if (Looks::LookText(g.preset, text, &g.error)) Looks::ParsePreset(text, g.ini);
    g.loaded = g.error.empty() && g.ini.error.empty();
    if (!g.ini.error.empty()) g.error = g.ini.error;
    // ApexOff= (Apex's own key, ignored by ReShade): shaders the look keeps in its list switched off; they are not in
    // Techniques=, so ReShade does not run them either. They join the .ini's entries at their TechniqueSorting place.
    g.iniOff.clear();
    if (auto top = g.ini.sections.find(""); top != g.ini.sections.end())
        if (auto it = std::find_if(top->second.begin(), top->second.end(), [](const auto& kv) { return _stricmp(kv.first.c_str(), "ApexOff") == 0; });
            it != top->second.end())
        {
            const std::vector<std::string> sorting = Looks::PresetSorting(g.ini);
            auto rank = [&](const std::string& k) {
                for (size_t i = 0; i < sorting.size(); ++i) if (_stricmp(sorting[i].c_str(), k.c_str()) == 0) return i;
                return sorting.size();
            };
            for (size_t a = 0; a < it->second.size() && g.iniOff.size() < kMaxListEntries;)
            {
                size_t b = it->second.find(',', a);
                if (b == std::string::npos) b = it->second.size();
                std::string key = it->second.substr(a, b - a);
                a = b + 1;
                while (!key.empty() && (key.back() == ' ' || key.back() == '\t')) key.pop_back();
                while (!key.empty() && (key.front() == ' ' || key.front() == '\t')) key.erase(0, 1);
                const size_t at = key.find('@');
                if (at == std::string::npos || at == 0 || key.size() > 200 || g.iniOff.count(Lower(key))) continue;
                if (std::any_of(g.ini.order.begin(), g.ini.order.end(), [&](const auto& e) { return Lower(EntryKey(e)) == Lower(key); })) continue;
                Looks::PresetEntry e;
                e.technique = key.substr(0, at);
                e.file = key.substr(at + 1);
                const size_t r = rank(key);
                auto pos = std::find_if(g.ini.order.begin(), g.ini.order.end(), [&](const auto& x) { return rank(EntryKey(x)) > r; });
                g.ini.order.insert(pos, e);
                g.iniOff.insert(Lower(key));
            }
        }
    for (auto& e : g.ini.order) ResolveEntry(e);
    g.iniOrder = g.ini.order;
    g.iniKeys.clear();
    for (auto& e : g.iniOrder) g.iniKeys.insert(Lower(EntryKey(e)));
    RebuildOrder();
    if (g.loaded) LOG_INFO("[Looks] preset loaded: " + g.status);
    else
    {
        g.status = "Look: " + g.error;
        LOG_WARNING("[Looks] " + g.status);
    }
}

// The Shaders folder was compiled again: user shader indices changed, so every entry is looked up again
void ResolveShaders()
{
    for (auto& e : g.ini.order) ResolveEntry(e);
    for (auto& e : g.iniOrder) ResolveEntry(e);
    RebuildOrder();
}

// The .ini's values of run-list entry i, read again when the shader's parameters changed since the look was loaded (a
// shader compiled or recompiled later: its list was empty or of another size, and its rows read past it)
std::vector<float>& IniValues(size_t i)
{
    if (g.iniValues.size() < g.order.size()) g.iniValues.resize(g.order.size());
    std::vector<float>& v = g.iniValues[i];
    if (!Runnable(i)) return v;
    const LooksShader& d = Looks::Shader(g.order[i].shader);
    if (v.size() != (size_t)d.paramCount * 4)
    {
        v = Looks::PresetValues(g.ini, d, (g.order[i].alt.empty() ? g.order[i].file : g.order[i].alt).c_str());
        v.resize((size_t)d.paramCount * 4, 0.0f);
    }
    return v;
}

const float* ValuesFor(size_t entry)
{
    auto it = g.tweaks.find(g.order[entry].technique);
    std::vector<float>& ini = IniValues(entry);
    if (it != g.tweaks.end() && it->second.size() == ini.size()) return it->second.data();
    return ini.data();
}

// ---------------------------------------------------------------------------------------------- device state
// What the passes change (Looks::kSavedRenderStates, looks_runner.h): the built-in passes the first kBuiltIn* render
// states, sampler states and samplers and the PS constants their parameters use; a run with a player's effect
// (Fx::Instance::Run) all of the lists, every sampler, more PS constants, the VS constants and render targets 1..3.
constexpr const D3DRENDERSTATETYPE* kRS = Looks::kSavedRenderStates;
constexpr const D3DSAMPLERSTATETYPE* kSS = Looks::kSavedSamplerStates;
constexpr int kRSCount = Looks::kSavedRenderStateCount, kSSCount = Looks::kSavedSamplerStateCount;
constexpr DWORD kSamplers = Looks::kBuiltInSamplers, kAllSamplers = 16;
constexpr UINT kAllPSConsts = 224, kVSConsts = 256;

bool g_viewportSetSinceRt0 = true; // a SetViewport came after the last SetRenderTarget(0) through the hooks

struct SavedState
{
    IDirect3DSurface9* rt0 = nullptr; IDirect3DSurface9* ds = nullptr;
    IDirect3DPixelShader9* ps = nullptr; IDirect3DVertexShader9* vs = nullptr; IDirect3DVertexDeclaration9* decl = nullptr; DWORD fvf = 0;
    IDirect3DVertexBuffer9* stream0 = nullptr; UINT stream0Offset = 0, stream0Stride = 0;
    IDirect3DBaseTexture9* tex[kAllSamplers] = {}; DWORD rs[kRSCount] = {}; DWORD ss[kAllSamplers][kSSCount] = {};
    float psConst[kAllPSConsts * 4]; D3DVIEWPORT9 viewport{}; RECT scissor{};
    float vsConst[kVSConsts * 4];            // full only (okVsConst)
    IDirect3DSurface9* rtN[3] = {};          // render targets 1..3, full only
    // the vertex texture stages D3DVERTEXTEXTURESAMPLER0..3 and the sampler states Fx::Instance::Run sets there, full only
    static constexpr D3DSAMPLERSTATETYPE kVss[5] = { D3DSAMP_MINFILTER, D3DSAMP_MAGFILTER, D3DSAMP_MIPFILTER, D3DSAMP_ADDRESSU, D3DSAMP_ADDRESSV };
    IDirect3DBaseTexture9* vtex[4] = {}; DWORD vss[4][5] = {}; bool okVtex = false;
    bool full = false;                       // a player's effect runs: everything it changes is kept
    DWORD samplers = kSamplers; int rsCount = Looks::kBuiltInRenderStates, ssCount = Looks::kBuiltInSamplerStates; UINT psConsts = 3;
    IDirect3DDevice9* captured = nullptr;
    std::string failed; // the getters that failed (a D3D9 wrapper such as the RTX Remix bridge may not answer all of them)
    bool okConst = false, okVsConst = false, okView = false, okScissor = false, okStream = false, okFvf = false;
    bool okSamplerStates = false, okRenderStates = false;
    bool gameViewport = true; // the game set a viewport after binding render target 0 (g_viewportSetSinceRt0 at Capture)

    ~SavedState() { if (captured) Restore(captured); else Release(); }
    // builtInConsts: the PS constants the built-in steps write (Looks::PsConstsUsed)
    bool Capture(IDirect3DDevice9* dev, bool all, UINT builtInConsts)
    {
        full = all;
        psConsts = (std::min)(builtInConsts, kAllPSConsts);
        if (full) { samplers = kAllSamplers; rsCount = kRSCount; ssCount = kSSCount; psConsts = kAllPSConsts; }
        auto note = [&](bool good, const char* name) { if (!good) failed += failed.empty() ? name : std::string(", ") + name; return good; };
        // Only the render target is required. Everything else is also kept by the D3DSBT_ALL state block around the
        // runs; a getter that fails is noted and its value is simply not put back here.
        D3D9Hooks::SettleDeferredShaders(dev);
        const bool okRt = note(SUCCEEDED(dev->GetRenderTarget(0, &rt0)) && rt0, "GetRenderTarget");
        const HRESULT dr = ExtraHooks::RawGetDepthStencilSurface(dev, &ds);
        note(SUCCEEDED(dr) || (dr == D3DERR_NOTFOUND && !ds), "GetDepthStencilSurface");
        if (!note(SUCCEEDED(dev->GetPixelShader(&ps)), "GetPixelShader")) ps = nullptr;
        if (!note(SUCCEEDED(dev->GetVertexShader(&vs)), "GetVertexShader")) vs = nullptr;
        if (!note(SUCCEEDED(dev->GetVertexDeclaration(&decl)), "GetVertexDeclaration")) decl = nullptr;
        okFvf = note(SUCCEEDED(dev->GetFVF(&fvf)), "GetFVF");
        // RTX Remix bridges before patch 0012 answer a declaration older than the last SetFVF; restoring it drew the game's
        // UI and bloom with a game shader's layout (a red/green wash, a solid orange or black top-right quarter)
        if (okFvf) ExtraHooks::UseVertexInputSetLast(decl, fvf);
        okStream = note(SUCCEEDED(dev->GetStreamSource(0, &stream0, &stream0Offset, &stream0Stride)), "GetStreamSource");
        bool okTex = true, okSS = true, okRS = true;
        for (DWORD s = 0; s < samplers; ++s)
        {
            if (FAILED(dev->GetTexture(s, &tex[s]))) { tex[s] = nullptr; okTex = false; }
            for (int i = 0; i < ssCount; ++i) okSS &= SUCCEEDED(dev->GetSamplerState(s, kSS[i], &ss[s][i]));
        }
        for (int i = 0; i < rsCount; ++i) okRS &= SUCCEEDED(dev->GetRenderState(kRS[i], &rs[i]));
        note(okTex, "GetTexture"); note(okSS, "GetSamplerState"); note(okRS, "GetRenderState");
        okConst = note(SUCCEEDED(dev->GetPixelShaderConstantF(0, psConst, psConsts)), "GetPixelShaderConstantF");
        if (full)
        {
            okVsConst = note(SUCCEEDED(dev->GetVertexShaderConstantF(0, vsConst, kVSConsts)), "GetVertexShaderConstantF");
            for (DWORD r = 0; r < 3; ++r) if (FAILED(dev->GetRenderTarget(r + 1, &rtN[r]))) rtN[r] = nullptr; // NOTFOUND: none bound
            okVtex = true;
            for (DWORD v = 0; v < 4; ++v)
            {
                if (FAILED(dev->GetTexture(D3DVERTEXTEXTURESAMPLER0 + v, &vtex[v]))) { vtex[v] = nullptr; okVtex = false; }
                for (int i = 0; i < 5; ++i) okVtex &= SUCCEEDED(dev->GetSamplerState(D3DVERTEXTEXTURESAMPLER0 + v, kVss[i], &vss[v][i]));
            }
            note(okVtex, "vertex textures");
        }
        gameViewport = g_viewportSetSinceRt0;
        okView = note(SUCCEEDED(dev->GetViewport(&viewport)), "GetViewport");
        okScissor = note(SUCCEEDED(dev->GetScissorRect(&scissor)), "GetScissorRect");
        if (!failed.empty()) { static bool once = false; if (!once) { once = true; LOG_WARNING("[Looks] device getters that failed (not restored by hand): " + failed); } }
        if (!okRt) { Release(); return false; }
        okSamplerStates = okSS; okRenderStates = okRS;
        captured = dev;
        return true;
    }
    void Restore(IDirect3DDevice9* dev)
    {
        captured = nullptr;
        D3D9Hooks::CallOriginalSetRenderTarget(dev, 0, rt0); // resets the viewport, so it goes first
        if (full) for (DWORD r = 0; r < 3; ++r) D3D9Hooks::CallOriginalSetRenderTarget(dev, r + 1, rtN[r]);
        ExtraHooks::RawSetDepthStencilSurface(dev, ds);
        for (DWORD s = 0; s < samplers; ++s)
        {
            dev->SetTexture(s, tex[s]);
            if (okSamplerStates) for (int i = 0; i < ssCount; ++i) dev->SetSamplerState(s, kSS[i], ss[s][i]);
        }
        if (okRenderStates) for (int i = 0; i < rsCount; ++i) dev->SetRenderState(kRS[i], rs[i]);
        if (okConst) dev->SetPixelShaderConstantF(0, psConst, psConsts);
        if (okVsConst) dev->SetVertexShaderConstantF(0, vsConst, kVSConsts);
        if (full)
            for (DWORD v = 0; v < 4; ++v)
            {
                dev->SetTexture(D3DVERTEXTEXTURESAMPLER0 + v, vtex[v]);
                if (okVtex) for (int i = 0; i < 5; ++i) dev->SetSamplerState(D3DVERTEXTEXTURESAMPLER0 + v, kVss[i], vss[v][i]);
            }
        dev->SetPixelShader(ps);
        dev->SetVertexShader(vs);
        if (decl) dev->SetVertexDeclaration(decl); else if (okFvf) dev->SetFVF(fvf);
        if (okStream) dev->SetStreamSource(0, stream0, stream0Offset, stream0Stride); // DrawPrimitiveUP clears stream 0
        // Untouched since render target 0 was bound: SetRenderTarget(rt0) above already gave the whole target. An RTX Remix
        // client without bridge patch 0011 answers the bloom's small viewport there, and putting it back would shrink the
        // game's next back-buffer draws
        // shortcut: the scissor follows the viewport flag (SetScissorRect is not hooked in public builds)
        g_viewportSetSinceRt0 = gameViewport; // (a player's pass sets its own viewport through the hooks)
        if (gameViewport)
        {
            if (okView) dev->SetViewport(&viewport);
            if (okScissor) dev->SetScissorRect(&scissor);
        }
        Release();
    }
    void Release()
    {
        for (IUnknown* u : std::initializer_list<IUnknown*>{ rt0, ds, ps, vs, decl, stream0 }) if (u) u->Release();
        for (auto*& t : tex) if (t) { t->Release(); t = nullptr; }
        for (auto*& r : rtN) if (r) { r->Release(); r = nullptr; }
        for (auto*& t : vtex) if (t) { t->Release(); t = nullptr; }
        rt0 = nullptr; ds = nullptr; ps = nullptr; vs = nullptr; decl = nullptr; stream0 = nullptr;
    }
};

// ---------------------------------------------------------------------------------------------- the effect
// Why the look did or did not draw: logged once each time it changes, and shown in the developer's Live counters
std::string g_why = "not run yet (no scene boundary seen)";
std::string g_frameWhy;    // this frame's parts, joined; shown and logged at the next Present
bool g_frameTried = false; // a part was attempted this frame
void Why(const std::string& s)
{
    if (s == g_why) return;
    g_why = s;
    LOG_INFO("[Looks] " + g_why);
}
void PartWhy(std::string_view s) // appended in place: no allocation once the line has its size
{
    if (s.empty()) return;
    if (!g_frameWhy.empty()) g_frameWhy += "; then ";
    g_frameWhy += s;
}

// Where each shader runs. The game's frame: its 3D scene, then Apex's scene boundary (first depth-off back-buffer draw,
// Apex's post-scene effects; PostScene), then the UI, then the game's colour pass, which redraws the whole picture in
// 256x256 tiles with x (1 + 0.4) / (x + 0.4) (PostScene::ColourCurveLastFrame).
//  0 scene boundary   shaders that read depth: never over the UI
//  1 world            the look when "World only": right after the boundary's own draw when that is the game's bloom (a
//                     two-triangle strip), before the next back-buffer draw (the UI) or the colour pass's first copy,
//                     else at the boundary. Never inside the colour pass: tiles copied before the look were drawn back
//                     without it (two squares at the top left). The shaders are made for the picture after the game's
//                     curve (what "World and menus" and ReShade see), so they get it applied and their result is written
//                     back through its inverse (Frame::gameCurve)
//  2 end of frame     the look when "World and menus" (HUD included, like GShade)
// Outside a world only point 2 runs.
enum Where { kBoundary = 0, kWorld = 1, kEndOfFrame = 2 };
int WhereOf(size_t i)
{
    auto depthAt = [](size_t j) { return Runnable(j) && Looks::Shader(g.order[j].shader).needsDepth; };
    if (depthAt(i)) return kBoundary;
    // a shader listed before a depth shader runs before it, as in ReShade (the list's order): at the boundary too, else the
    // depth shader ran first (a tonemap listed before MXAO shaded MXAO's result instead of the other way round)
    for (size_t j = i + 1; j < g.order.size(); ++j)
        if (depthAt(j) && !IsOff(j)) return kBoundary;
    return g.onUi ? kEndOfFrame : kWorld;
}
bool g_ranThisFrame = false;      // end-of-frame part done
bool g_boundaryThisFrame = false; // scene boundary seen this frame
bool g_worldDone = false;         // the World only part ran this frame (PostScene can reach a second boundary)
bool g_worldPending = false;      // ... waits for the boundary's draw (the bloom) to be drawn
bool g_boundaryDraw = false;      // Looks' hook of the boundary's own draw comes next
float g_curve = 0.0f;             // the World only run: the game's colour curve still to come (0: none)
bool g_frameTicked = false;       // g_frame advanced this frame (framecount/frametime: once per frame, not per run point)
bool g_beforeLookDone = false;    // ApexCapture::BeforeLook called this frame (a split frame draws more than once)
unsigned g_frame = 0;
float g_wheel = 0;                 // mouse wheel notches of the last frame (mousewheel)
IDirect3DStateBlock9* g_sb = nullptr;      // D3DSBT_ALL around the runs: what a failed getter could not keep
IDirect3DSurface9* g_curRT0 = nullptr;     // identity only
IDirect3DSurface9* g_backBuffer = nullptr; // identity only
const char* g_mode = "";

// ---- ReShade Effect Shader Toggler configurations (features/looks_rest.h, the Advanced switch). A shader a group takes runs
// when the game draws with one of the group's shaders (before that draw, after it, or when the game then changes its
// render target), once a frame, on that render target, instead of at Apex's own points; one whose group did not run this
// frame runs at the end of the frame (REST: at Present). The others run where Apex puts them.
constexpr int kRestNone = -2, kRestLeftovers = -1;
struct RestRuntime
{
    bool on = false;                // the switch is on and the file has an active group
    Looks::Rest::Config cfg;
    std::string status;             // English, for the menu note and the log
    std::vector<std::string> modes; // per group: g_mode while it runs (stable pointers for the log line)
    std::unordered_map<IUnknown*, uint32_t> crc; // the game's shaders seen in a draw -> CRC32 of their bytecode (a reference each)
    IUnknown* lastVs = nullptr; uint32_t lastVsCrc = 0;
    IUnknown* lastPs = nullptr; uint32_t lastPsCrc = 0;
    std::vector<uint8_t> fired;     // per group: its effects ran this frame
    std::vector<uint8_t> ran;       // per run-list entry: run by a group this frame
    struct Pending { int group; IDirect3DSurface9* rt; bool afterDraw; IUnknown* vs; IUnknown* ps; }; // identities only (vs / ps: the matched stage's)
    std::vector<Pending> pending;
    UINT bbW = 0, bbH = 0;
    bool busy = false; // Looks runs now: draws of its own passes do not count
} g_rest;

uint64_t RestMask(size_t i) // the groups that take run-list entry i
{
    uint64_t m = 0;
    if (!g_rest.on || i >= g.order.size()) return 0;
    for (size_t k = 0; k < g_rest.cfg.groups.size() && k < 64; ++k)
        if (Looks::Rest::Takes(g_rest.cfg.groups[k], g.order[i].technique, g.order[i].file)) m |= 1ull << k;
    return m;
}
bool RestRan(size_t i) { return i < g_rest.ran.size() && g_rest.ran[i]; }

template <class S> uint32_t RestCrc(S* shader, IUnknown*& last, uint32_t& lastCrc)
{
    if (!shader) return 0;
    if (shader == last) return lastCrc;
    uint32_t c = 0;
    if (const auto it = g_rest.crc.find(shader); it != g_rest.crc.end()) c = it->second;
    else
    {
        UINT bytes = 0;
        std::vector<uint8_t> code;
        if (SUCCEEDED(shader->GetFunction(nullptr, &bytes)) && bytes >= 8 && bytes <= (1u << 20))
        {
            code.resize(bytes);
            if (FAILED(shader->GetFunction(code.data(), &bytes))) code.clear();
        }
        c = code.empty() ? 0 : Looks::Rest::Crc32(code.data(), code.size());
        if (g_rest.crc.size() >= 16384) return c; // (not kept: not remembered as the last one either)
        shader->AddRef(); // a reference: no address reuse
        g_rest.crc.emplace(shader, c);
    }
    last = shader;
    lastCrc = c;
    return c;
}

void ReleaseRestShaders()
{
    for (auto& [shader, c] : g_rest.crc) shader->Release();
    g_rest.crc.clear();
    g_rest.lastVs = g_rest.lastPs = nullptr;
}

std::wstring GameFolder()
{
    wchar_t exe[MAX_PATH] = {};
    const DWORD n = GetModuleFileNameW(nullptr, exe, MAX_PATH);
    std::wstring dir(exe, n);
    const size_t slash = dir.find_last_of(L"\\/");
    return slash == std::wstring::npos ? std::wstring() : dir.substr(0, slash + 1);
}

// Reads the file when the switch turns on (and at install): the Apex Radiance folder first, then the game's (REST's own)
void LoadRest()
{
    ReleaseRestShaders();
    g_rest.cfg = {};
    g_rest.on = false;
    g_rest.status.clear();
    g_rest.modes.clear();
    if (!g.restConfig) return;
    const std::pair<std::wstring, const char*> places[] = { { ApexPaths::ApexDirectory(), "the Apex Radiance folder" }, { GameFolder(), "the game's folder" } };
    for (const auto& [dir, where] : places)
    {
        if (dir.empty()) continue;
        std::ifstream f(dir + L"ReshadeEffectShaderToggler.ini", std::ios::binary);
        if (!f) continue;
        std::stringstream text;
        text << f.rdbuf();
        if (text.str().size() > (4u << 20) || !Looks::Rest::Parse(text.str(), g_rest.cfg))
        {
            g_rest.cfg = {};
            g_rest.status = std::format("ReshadeEffectShaderToggler.ini in {} has no shader group", where);
            LOG_WARNING("[Looks] REST: " + g_rest.status);
            return;
        }
        int active = 0;
        std::string names;
        for (const Looks::Rest::Group& grp : g_rest.cfg.groups)
        {
            static const char* const kWhere[] = { "before the draw", "after the draw", "on render target change" };
            g_rest.modes.push_back(std::format("for the REST group \"{}\" ({})", grp.name, kWhere[grp.location]));
            if (!grp.active) continue;
            ++active;
            names += std::format("{}\"{}\" ({} shaders, {})", names.empty() ? "" : ", ", grp.name, grp.vs.size() + grp.ps.size(), kWhere[grp.location]);
        }
        g_rest.on = active > 0;
        g_rest.fired.assign(g_rest.cfg.groups.size(), 0); // (installed mid-frame: draws come before the next Present)
        g_rest.ran.assign(g.order.size(), 0);
        g_rest.pending.clear();
        g_rest.status = std::format("ReshadeEffectShaderToggler.ini in {}: {} active of {} groups{}{}", where, active, g_rest.cfg.groups.size(),
                                    names.empty() ? "" : ": ", names);
        LOG_INFO("[Looks] REST: " + g_rest.status);
        for (const std::string& note : g_rest.cfg.notes) LOG_INFO("[Looks] REST: " + note);
        return;
    }
    g_rest.status = "No ReshadeEffectShaderToggler.ini next to the game or in the Apex Radiance folder";
    LOG_INFO("[Looks] REST: " + g_rest.status);
}

void EffectImpl(IDirect3DDevice9* dev, bool atEndScene, unsigned mask, int restGroup = kRestNone);
void RestFlush(IDirect3DDevice9* dev, bool afterDrawOnly, IUnknown* vs, IUnknown* ps);
void World(IDirect3DDevice9* dev, bool curveAhead);
void Effect(IDirect3DDevice9* dev)
{
    g_boundaryThisFrame = true;
    // depth shaders (MXAO, SMAA's depth pass, fog, DOF) run here, before the game's colour curve: like the World run they get
    // the picture after the curve (what ReShade sees at Present) and are written back through its inverse. Without it MXAO's
    // shade came out about half as strong in mid and bright tones and SMAA found fewer dark edges
    g_curve = !PostScene::ColourTilesStarted() ? PostScene::ColourCurveLastFrame() : 0.0f;
    g_mode = g_curve > 0.0f ? "at the scene boundary, under the game's colour curve" : "at the scene boundary";
    EffectImpl(dev, false, 1u << kBoundary);
    g_curve = 0.0f;
    if (g.onUi || g_worldDone) return;
    if (PostScene::BoundaryOnDraw()) { g_worldPending = g_boundaryDraw = true; return; } // decided at that draw (OnDraw)
    World(dev, !PostScene::ColourTilesStarted());
}

// The World only part. curveAhead: the game's colour pass is still to come this frame (it came last frame)
void World(IDirect3DDevice9* dev, bool curveAhead)
{
    g_worldPending = g_boundaryDraw = false;
    if (std::exchange(g_worldDone, true)) return;
    g_curve = curveAhead ? PostScene::ColourCurveLastFrame() : 0.0f;
    g_mode = g_curve > 0.0f ? "before the interface, under the game's colour curve" : "before the interface";
    EffectImpl(dev, false, 1u << kWorld);
    g_curve = 0.0f;
}

bool OnBackBuffer(IDirect3DDevice9* dev) // asked, not tracked: the High-precision scene binds its target outside the hooks
{
    IDirect3DSurface9* rt = nullptr;
    const bool on = SUCCEEDED(dev->GetRenderTarget(0, &rt)) && rt && rt == g_backBuffer;
    if (rt) rt->Release();
    return on;
}

void OnDraw(D3D9Hooks::DeviceContext& ctx, bool isStripOfTwo)
{
    if (!g_worldPending || DepthShare::InternalPass()) return;
    if (std::exchange(g_boundaryDraw, false)) { if (!isStripOfTwo) World(ctx.device, true); return; } // the bloom: after it
    // the bloom chain's own targets, and more scene (interiors, a boundary inside the scene): not yet
    DWORD z = ctx.ZEnable();
    if (z != D3DZB_FALSE && !ctx.ZWriteEnable() && ctx.ZFunc() == D3DCMP_ALWAYS) z = D3DZB_FALSE; // UI glass passes
    if (z == D3DZB_FALSE && OnBackBuffer(ctx.device)) World(ctx.device, true);
}

void AtEndScene(IDirect3DDevice9* dev)
{
    if (g_ranThisFrame || !g.active || !dev) return;
    IDirect3DSurface9* bb = nullptr; IDirect3DSurface9* rt = nullptr;
    const bool okBb = SUCCEEDED(dev->GetBackBuffer(0, 0, D3DBACKBUFFER_TYPE_MONO, &bb)) && bb;
    const bool okRt = SUCCEEDED(dev->GetRenderTarget(0, &rt)) && rt;
    const bool onBackBuffer = okBb && okRt && bb == rt;
    if (bb) bb->Release();
    if (rt) rt->Release();
    if (!onBackBuffer) return; // an off-screen pass (reflection, thumbnail): wait for the frame's own EndScene
    g_ranThisFrame = true;
    if (g_rest.on)
    {
        RestFlush(dev, false, nullptr, nullptr);
        if (g_worldPending) World(dev, false); // (the world part first, as on any other frame)
        if (WorldSession::InWorld()) // a group that did not run this frame: its shaders at the end of the frame (REST: at Present)
        {
            g_mode = "for REST groups that did not run this frame, at the end of the frame";
            EffectImpl(dev, true, 0, kRestLeftovers);
        }
    }
    if (g_worldPending) World(dev, false); // the frame ended on the bloom (no UI, no colour pass)
    if (!g.onUi) return; // UI left clean: nothing at the end of frame
    g_mode = "at the end of frame";
    EffectImpl(dev, true, 1u << kEndOfFrame);
}

// The scene depth (DepthBlur's INTZ copy) is asked for only while a shader that is on reads it
// (at once when one turns on; given back after 120 frames without one, so switching shaders never rebuilds it)
bool g_depthHeld = false;
int g_depthIdle = 0; // frames without a depth shader while held
void SyncDepth(bool installed)
{
    bool want = false;
    for (size_t i = 0; installed && !want && i < g.order.size(); ++i) want = Runnable(i) && !IsOff(i) && Looks::Shader(g.order[i].shader).needsDepth;
    g_depthIdle = want ? 0 : g_depthIdle + 1;
    if (want && !g_depthHeld) { DepthShare::Request(true); g_depthHeld = true; }
    else if (g_depthHeld && (!installed || g_depthIdle > 120)) { DepthShare::Request(false); g_depthHeld = false; }
}

void OnPresent(IDirect3DDevice9* dev)
{
    if (!g_frameWhy.empty()) Why(g_frameWhy);
    else if (g_frameTried) { static const std::string kNothing = "nothing to run: every shader is switched off or not built in"; Why(kNothing); }
    g_frameWhy.clear();
    g_frameTried = false;
    g_ranThisFrame = g_boundaryThisFrame = g_worldDone = g_worldPending = g_boundaryDraw = g_beforeLookDone = g_frameTicked = false;
    g_rest.fired.assign(g_rest.cfg.groups.size(), 0);
    g_rest.ran.assign(g.order.size(), 0);
    g_rest.pending.clear();
    IDirect3DSurface9* s = nullptr;
    g_backBuffer = nullptr;
    D3DSURFACE_DESC bd{};
    if (dev && SUCCEEDED(dev->GetBackBuffer(0, 0, D3DBACKBUFFER_TYPE_MONO, &s)) && s) { g_backBuffer = s; s->GetDesc(&bd); s->Release(); }
    g_rest.bbW = bd.Width;
    g_rest.bbH = bd.Height;
    Looks::Packs::BeginFrame(); // the pack list changes only here, between menu frames
    g_wheel = Overlay::TakeWheel();
    if (static bool adapter = false; !adapter && dev) // __VENDOR__ / __DEVICE__ before the first scan compiles
    {
        adapter = true;
        IDirect3D9* d3d = nullptr; D3DDEVICE_CREATION_PARAMETERS cp{}; D3DADAPTER_IDENTIFIER9 id{};
        if (SUCCEEDED(dev->GetDirect3D(&d3d)) && d3d)
        {
            if (SUCCEEDED(dev->GetCreationParameters(&cp)) && SUCCEEDED(d3d->GetAdapterIdentifier(cp.AdapterOrdinal, 0, &id))) Looks::Fx::SetAdapter(id.VendorId, id.DeviceId);
            d3d->Release();
        }
    }
    if (Looks::Fx::Poll(bd.Width, bd.Height)) ResolveShaders(); // a scan of the Shaders folder finished (part of it)
    bool wantHair = false;
    for (size_t i = 0; g.active && !wantHair && i < g.order.size(); ++i)
        wantHair = Runnable(i) && !IsOff(i) && g.hair.count(g.order[i].technique);
    SimMask::Want(wantHair);
    SyncDepth(g.active);
    if (dev && SUCCEEDED(dev->GetRenderTarget(0, &s)) && s) { g_curRT0 = s; s->Release(); }
}

// A group's run on the render target bound now (the one its draw drew on; a group whose size does not match waits for its
// next draw when it asks for that, else gives up for the frame)
void RestRun(IDirect3DDevice9* dev, int gi, IDirect3DSurface9* expected)
{
    IDirect3DSurface9* rt = nullptr;
    D3DSURFACE_DESC d{};
    if (FAILED(dev->GetRenderTarget(0, &rt)) || !rt) return;
    rt->GetDesc(&d);
    const bool same = !expected || rt == expected;
    rt->Release();
    const Looks::Rest::Group& grp = g_rest.cfg.groups[gi];
    // REST queues the group's effects again at each of its draws until they ran on a render target of the screen's size
    static const D3DFORMAT kColour[] = { D3DFMT_A8R8G8B8, D3DFMT_X8R8G8B8, D3DFMT_A2R10G10B10, D3DFMT_A2B10G10R10, D3DFMT_A16B16G16R16,
                                         D3DFMT_A16B16G16R16F, D3DFMT_A32B32G32R32F, D3DFMT_R5G6B5, D3DFMT_X1R5G5B5, D3DFMT_A1R5G5B5 };
    const bool colour = std::find(std::begin(kColour), std::end(kColour), d.Format) != std::end(kColour); // (REST: IsColorBuffer)
    if (!same || !colour || !Looks::Rest::SizeMatches(grp, d.Width, d.Height, g_rest.bbW, g_rest.bbH)) return;
    g_rest.fired[gi] = 1;
    g_curve = !PostScene::ColourTilesStarted() ? PostScene::ColourCurveLastFrame() : 0.0f; // as at the scene boundary
    g_mode = g_rest.modes[gi].c_str();
    EffectImpl(dev, false, 0, gi);
    g_curve = 0.0f;
}

// The runs waiting for the matched draw to be done (afterDrawOnly) or for the render target to change (all)
void RestFlush(IDirect3DDevice9* dev, bool afterDrawOnly, IUnknown* vs = nullptr, IUnknown* ps = nullptr)
{
    if (g_rest.busy) return;
    for (size_t k = 0; k < g_rest.pending.size();)
    {
        const auto p = g_rest.pending[k];
        // after the draw = after the run of draws with the matched shader (REST: when that stage's shader changes)
        if (afterDrawOnly && (!p.afterDraw || (p.vs && p.vs == vs) || (p.ps && p.ps == ps))) { ++k; continue; }
        g_rest.pending.erase(g_rest.pending.begin() + k);
        RestRun(dev, p.group, p.rt);
    }
}

void RestOnDraw(IDirect3DDevice9* dev)
{
    if (!g_rest.on || g_rest.busy || !g.active || !g.loaded || DepthShare::InternalPass()) return;
    if (g_rest.fired.size() != g_rest.cfg.groups.size()) g_rest.fired.assign(g_rest.cfg.groups.size(), 0);
    if (g_rest.ran.size() != g.order.size()) g_rest.ran.assign(g.order.size(), 0); // (a look loaded mid-frame)
    IDirect3DVertexShader9* vs = D3D9Hooks::BoundVertexShader(dev);
    IDirect3DPixelShader9* ps = D3D9Hooks::BoundPixelShader(dev);
    if (!g_rest.pending.empty()) RestFlush(dev, true, vs, ps); // the matched draws before this one are done
    const uint32_t vh = RestCrc(vs, g_rest.lastVs, g_rest.lastVsCrc);
    const uint32_t ph = RestCrc(ps, g_rest.lastPs, g_rest.lastPsCrc);
    for (size_t gi = 0; gi < g_rest.cfg.groups.size(); ++gi)
    {
        const Looks::Rest::Group& grp = g_rest.cfg.groups[gi];
        const bool byVs = vh && grp.vs.count(vh), byPs = ph && grp.ps.count(ph);
        if (g_rest.fired[gi] || !grp.active || !(byVs || byPs)) continue;
        if (std::any_of(g_rest.pending.begin(), g_rest.pending.end(), [gi](const RestRuntime::Pending& p) { return p.group == (int)gi; })) continue;
        if (grp.location == Looks::Rest::kBeforeDraw) { RestRun(dev, (int)gi, nullptr); continue; }
        IDirect3DSurface9* rt = nullptr;
        if (FAILED(dev->GetRenderTarget(0, &rt)) || !rt) continue;
        rt->Release();
        g_rest.pending.push_back({ (int)gi, rt, grp.location == Looks::Rest::kAfterDraw, byVs ? vs : nullptr, byVs ? nullptr : ps });
    }
}

void EffectImpl(IDirect3DDevice9* dev, bool atEndScene, unsigned mask, int restGroup)
{
    struct Busy { bool was = std::exchange(g_rest.busy, true); ~Busy() { g_rest.busy = was; } } busy; // (REST: no run inside a run)
    g_frameTried = true;
    if (!g.active || !g.loaded) { PartWhy(g.loaded ? "waiting: off" : "waiting: preset not loaded"); return; }
    if (GetTickCount64() < g_holdUntil) { PartWhy("held: showing the game without the look"); return; }
    if (!atEndScene && !WorldSession::InWorld()) { PartWhy("waiting: not in a world"); return; }
    if (!ShaderCache::PrecompileComplete()) { PartWhy("waiting: Apex shaders still compiling"); return; }
    auto inPart = [mask, restGroup](size_t i) {
        const uint64_t rest = RestMask(i);
        if (restGroup >= 0) return ((rest >> restGroup) & 1u) != 0 && !RestRan(i);
        if (restGroup == kRestLeftovers) return rest != 0 && !RestRan(i);
        return rest == 0 && ((mask >> WhereOf(i)) & 1u) != 0; // a REST group's shader runs only at its group's draw
    };

    static std::vector<Looks::Step> steps; // in the run list's order; kept between frames (no allocation per frame)
    steps.clear();
    bool anySkipHair = false;
    int keptOffUi = 0;
    bool userFx = false;
    for (size_t i = 0; i < g.order.size(); ++i)
    {
        if (!Runnable(i) || IsOff(i)) continue;
        if (!inPart(i)) { if (atEndScene && restGroup == kRestNone) ++keptOffUi; continue; } // depth shaders: world only, never over the UI
        const auto hair = g.hair.find(g.order[i].technique);
        steps.push_back({ g.order[i].shader, ValuesFor(i), hair != g.hair.end() ? hair->second : 1.0f });
        anySkipHair |= hair != g.hair.end();
        if (restGroup != kRestNone && i < g_rest.ran.size()) g_rest.ran[i] = 1; // once a frame, also when it does not draw
        userFx |= Looks::IsUserShader(g.order[i].shader);
    }
    if (steps.empty()) return; // nothing of this part is on

    IDirect3DSurface9* rt = nullptr;
    if (FAILED(dev->GetRenderTarget(0, &rt)) || !rt) { PartWhy("stopped: GetRenderTarget failed"); return; }
    D3DSURFACE_DESC rd{};
    rt->GetDesc(&rd);
    if (!g_beforeLookDone) ApexCapture::BeforeLook(dev, rt); // [capture] look = without | both: the frame before the look (only while a capture wants it); once a frame
    g_beforeLookDone = true;
    // Strength 0 (a blend factor that rounds to 0, as Runner::Run computes it): the write-back keeps the destination x 1 and
    // adds the source x 0, the picture as it was, so nothing runs
    if (g.mix * 255.0f + 0.5f < 1.0f) { PartWhy("strength 0: nothing to draw"); rt->Release(); return; }

    // Depth only when it is the scene's own depth bound right now (not a reflection or UI pass)
    IDirect3DTexture9* depth = DepthShare::Texture();
    if (depth)
    {
        IDirect3DSurface9* ds = nullptr;
        ExtraHooks::RawGetDepthStencilSurface(dev, &ds);
        // A REST group's run also takes it when its draw has none bound (the interface's) once this frame's scene boundary
        // has passed: the shared copy holds the whole scene then, as ReShade's depth does
        const bool bound = ds && ds == DepthShare::Surface();
        if (!(bound || (restGroup != kRestNone && g_boundaryThisFrame)) || !PostScene::SceneDepthValid()) depth = nullptr;
        if (ds) ds->Release();
    }

    {
        SavedState saved;
        if (!saved.Capture(dev, userFx, (UINT)Looks::PsConstsUsed(steps))) { PartWhy("stopped: device state could not be read (" + saved.failed + ")"); rt->Release(); return; }
        ExtraHooks::RawSetDepthStencilSurface(dev, nullptr); // depth is sampled, so it must not be bound
        // Everything the passes change is put back by hand (SavedState). Only when a getter failed (a D3D9 wrapper such as
        // the RTX Remix bridge may not answer all of them) does a D3DSBT_ALL state block keep what could not be read.
        IDirect3DStateBlock9* sb = nullptr;
        if (!saved.failed.empty())
        {
            D3D9Hooks::SettleDeferredShaders(dev);
            if (!g_sb) dev->CreateStateBlock(D3DSBT_ALL, &g_sb);
            if (g_sb && SUCCEEDED(g_sb->Capture())) sb = g_sb;
        }

        // One tick per game frame, not per run point (a shader that alternates on FRAMECOUNT parity would otherwise see
        // the same parity at both run points of a frame)
        if (!g_frameTicked) { g_frameTicked = true; ++g_frame; }

        Looks::Frame f;
        f.dev = dev; f.target = rt; f.width = rd.Width; f.height = rd.Height;
        f.depth = depth; f.mix = g.mix; f.frame = g_frame; f.gameCurve = g_curve;
        f.wheel = g_wheel; f.overlayOpen = Overlay::IsVisible();
        if (anySkipHair && depth)
            if (const SimMask::View m = SimMask::Current(); m.width == rd.Width && m.height == rd.Height)
                f.simOpaque = m.opaque, f.simTransparent = m.transparent;
        GpuTrace::MarkIfOn(g_mode); // (the last steps of a session that does not close: where Looks runs, then its shaders)
        for (const Looks::Step& s : steps) GpuTrace::MarkIfOn(Looks::Shader(s.shader).technique);
        const bool drew = g.runner.Run(f, steps);
        {
            // The line is only rebuilt when one of its parts changed, not at every run point
            struct Key
            {
                const char* mode; UINT w, h; int fmt; bool depth; bool drew; size_t steps; int kept; float mix; bool boundary;
                bool operator==(const Key&) const = default;
            };
            static Key lastKey[4];
            static std::vector<std::string> lastSkipped[4];
            static std::string lastLine[4];
            const Key k{ g_mode, rd.Width, rd.Height, (int)rd.Format, depth != nullptr, drew, steps.size(), keptOffUi, g.mix, g_boundaryThisFrame };
            const std::vector<std::string>& skipped = g.runner.skipped();
            const int slot = restGroup != kRestNone ? 3 : atEndScene ? 2 : (mask & (1u << kBoundary)) ? 0 : 1;
            if (lastLine[slot].empty() || !(k == lastKey[slot]) || skipped != lastSkipped[slot])
            {
                std::string s = std::format("drawing {} on {}x{} (format {}), depth {}: {} shaders, {}, mix {:.0f}%",
                    g_mode, rd.Width, rd.Height, (int)rd.Format, depth ? "yes" : "no", steps.size(), drew ? "drew" : "nothing drawn", g.mix * 100.0f);
                if (keptOffUi) s += std::format("; {} kept off the UI (depth{})", keptOffUi, g_boundaryThisFrame ? ", run on the world before it" : "");
                if (!skipped.empty()) { s += "; skipped:"; for (auto& sk : skipped) s += " " + sk; }
                lastLine[slot] = std::move(s);
                lastKey[slot] = k;
                lastSkipped[slot] = skipped;
            }
            PartWhy(lastLine[slot]);
            if (g.skipped != skipped) g.skipped = skipped;
        }
        if (sb) sb->Apply();
    } // render target + depth restored here
    rt->Release();
}

void ReleaseGpu()
{
    g.runner.Release();
    Looks::Fx::ReleaseGpu();
    if (g_sb) g_sb->Release(), g_sb = nullptr;
}

void SetOrder()
{
    const int want = g.beforeColor ? kOrderBeforeColor : kOrderAfterColor;
    if (g.active && want != g.postOrder) { PostScene::Remove(Effect); PostScene::Add(want, Effect, false); }
    g.postOrder = want;
}

void OnPreReset(IDirect3DDevice9*) { ReleaseGpu(); }

// Room for one more of the player's effects: under the RTX Remix bridge their render targets and textures live in the
// bridge's 64-bit process, so no total limit; in the game's own process the 384 MB of DefaultRoom
bool LooksRoom(uint64_t running, uint64_t more, std::string* why) { return Platform::RemixBridge() || Looks::Fx::DefaultRoom(running, more, why); }
void RestartEffects(IDirect3DDevice9*) { ReleaseGpu(); }

// ---------------------------------------------------------------------------------------------- changes
// A newly chosen look starts as its .ini has it
void SelectLook(const std::string& ref)
{
    g.preset = ref;
    g.off.clear(); g.on.clear(); g.removed.clear(); g.extra.clear(); g.runOrder.clear(); g.tweaks.clear(); g.defs.clear(); g.hair.clear();
    LoadPreset();
    g.runner.Release();
}

void RemoveExtra(const std::string& key)
{
    const std::string k = Lower(key);
    g.extra.erase(std::remove_if(g.extra.begin(), g.extra.end(), [&](const std::string& x) { return Lower(x) == k; }), g.extra.end());
}

// A switch in the run list: switched off, a shader stays in the list (dimmed, its values kept) until it is removed
void SwitchEntry(size_t i, bool on)
{
    const std::string& t = g.order[i].technique;
    if (OffInFile(i)) { if (on) g.on.insert(t); else g.on.erase(t); }
    else if (on) g.off.erase(t);
    else g.off.insert(t);
}

// The trash: the shader stops running and stays listed with Restore until the look is saved (then it leaves the file)
// or put back as saved. Only a set changes: the list is not rebuilt while its rows draw.
void RemoveEntry(size_t i, bool removed)
{
    if (removed) g.removed.insert(Lower(EntryKey(g.order[i])));
    else g.removed.erase(Lower(EntryKey(g.order[i])));
}

// Changes to the run list asked for by a row are applied after the whole list is drawn: a row keeps references
// into g.order while it draws, and rebuilding the list under it read freed memory
struct DragMove { size_t i = 0; int dir = 0; } g_dragMove; // a row held by its grip (or Run earlier / later) passed a neighbour

// Swaps run-list entry i with the runnable entry before (dir -1) or after (dir +1) it
void Move(size_t i, int dir)
{
    int j = (int)i;
    do j += dir; while (j >= 0 && j < (int)g.order.size() && (!Runnable((size_t)j) || IsRemoved((size_t)j))); // the rows shown with a position
    if (j < 0 || j >= (int)g.order.size()) return;
    g.runOrder.clear();
    for (auto& e : g.order) g.runOrder.push_back(EntryKey(e));
    std::swap(g.runOrder[i], g.runOrder[(size_t)j]);
    RebuildOrder();
}

// Adds a shader at the end of the run list (or switches the .ini's own one back on). A pack's shader not compiled yet
// joins the list at once and compiles (RebuildOrder asks for its file).
void AddShader(const std::string& technique, const std::string& file)
{
    const std::string key = technique + "@" + file;
    g.off.erase(technique);
    for (size_t i = 0; i < g.order.size(); ++i)
        if (g.order[i].technique == technique && OffInFile(i)) g.on.insert(technique); // one the file keeps off: on again
    g.removed.erase(Lower(key));
    if (InIni(key)) return;
    RemoveExtra(key);
    g.extra.push_back(key);
    g.runOrder.clear();
    for (auto& e : g.order) g.runOrder.push_back(EntryKey(e));
    g.runOrder.push_back(key);
    RebuildOrder();
}

bool InRunList(int shader)
{
    for (size_t i = 0; i < g.order.size(); ++i) if (g.order[i].shader == shader && !IsOff(i)) return true;
    return false;
}

bool InRunList(const std::string& technique, const std::string& file)
{
    for (size_t i = 0; i < g.order.size(); ++i)
        if (g.order[i].technique == technique && _stricmp(g.order[i].file.c_str(), file.c_str()) == 0 && !IsOff(i)) return true;
    return false;
}

int Diffs(const std::vector<float>& a, const std::vector<float>& b)
{
    if (a.size() != b.size()) return 0;
    int n = 0;
    for (size_t k = 0; k < a.size(); ++k) n += std::fabs(a[k] - b[k]) > 1e-5f * (std::max)(1.0f, std::fabs(b[k]));
    return n;
}

// How many values of run-list entry i differ from the .ini (0 = as the .ini has it)
int EditedValues(size_t i)
{
    auto it = g.tweaks.find(g.order[i].technique);
    return it == g.tweaks.end() || !Runnable(i) ? 0 : Diffs(it->second, IniValues(i));
}

// Run-list entry i's file has quality settings (definitions) edited here
bool DefsEdited(size_t i) { return g.defs.count(Lower(g.order[i].alt.empty() ? g.order[i].file : g.order[i].alt)) != 0; }

bool AnyEdited()
{
    for (size_t i = 0; i < g.order.size(); ++i) if (EditedValues(i)) return true;
    return !g.defs.empty();
}

// The look differs from its file: anything switched, added, removed, moved, or a value or quality setting edited here.
// These changes live in Apex's settings (saved by itself); the file changes only with Save.
bool Dirty()
{
    return !g.off.empty() || !g.on.empty() || !g.extra.empty() || !g.runOrder.empty() || !g.removed.empty() || !g.hair.empty() || AnyEdited();
}

// Back to the look as its file has it (the undo toast can bring the changes back)
void PutBackAsSaved()
{
    g.off.clear(); g.on.clear(); g.extra.clear(); g.runOrder.clear(); g.removed.clear(); g.tweaks.clear(); g.defs.clear(); g.hair.clear();
    RebuildOrder(); // also pushes the definitions
}

// What Save would write, one English line per shader (shown translated), at most `max` lines
std::vector<std::string> ChangeLines(size_t max)
{
    std::vector<std::string> out;
    auto add = [&](std::string s) { if (out.size() < max) out.push_back(std::move(s)); };
    for (size_t i = 0; i < g.order.size(); ++i)
    {
        const std::string& t = g.order[i].technique;
        const bool fileOff = OffInFile(i);
        if (IsRemoved(i)) add(I18n::Trf("{} removed", t));
        else if (!InIni(EntryKey(g.order[i]))) add(I18n::Trf("{} added", t));
        else if (IsOff(i) != fileOff) add(I18n::Trf(IsOff(i) ? "{} turned off" : "{} turned on", t));
        else if (EditedValues(i) || DefsEdited(i)) add(I18n::Trf("{} changed", t));
    }
    if (!g.runOrder.empty()) add(I18n::Tr("Order changed"));
    return out;
}

// ---------------------------------------------------------------------------------------------- Save as a new look
// The look as it runs now, as ReShade preset text: Techniques= (the ones on, in run order), TechniqueSorting= (run list
// first, then the rest of the source's sorting), the source's other top lines and its [File.fx] sections, with the
// values of every built-in shader in the run list as they are now.
// read: false when the look's own text could not be read (then nothing may be written: its other lines would be lost)
std::string LookAsText(bool* read = nullptr)
{
    std::string text;
    const bool ok = Looks::LookText(g.preset, text);
    if (read) *read = ok;
    if (text.size() >= 3 && (unsigned char)text[0] == 0xEF && (unsigned char)text[1] == 0xBB && (unsigned char)text[2] == 0xBF) text.erase(0, 3);
    const std::string nl = text.find("\r\n") != std::string::npos ? "\r\n" : "\n";
    std::vector<std::string> top;
    std::vector<std::pair<std::string, std::vector<std::string>>> secs;
    for (size_t pos = 0; pos < text.size();)
    {
        size_t e = text.find('\n', pos); if (e == std::string::npos) e = text.size();
        std::string line = text.substr(pos, e - pos);
        pos = e + 1;
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.size() > 2 && line.front() == '[' && line.back() == ']') { secs.push_back({ line.substr(1, line.size() - 2), {} }); continue; }
        (secs.empty() ? top : secs.back().second).push_back(line);
    }
    while (!top.empty() && top.back().empty()) top.pop_back();
    for (auto& s : secs) while (!s.second.empty() && s.second.back().empty()) s.second.pop_back();
    auto setLine = [](std::vector<std::string>& lines, const std::string& key, const std::string& value) {
        for (auto& l : lines)
            if (l.size() > key.size() && l.compare(0, key.size(), key) == 0 && l[key.size()] == '=') { l = key + "=" + value; return; }
        lines.push_back(key + "=" + value);
    };
    std::string on, offList, sorting;
    std::set<std::string> listed;
    for (size_t i = 0; i < g.order.size(); ++i)
    {
        if (IsRemoved(i)) continue; // leaves the file
        const std::string k = EntryKey(g.order[i]);
        if (!IsOff(i)) on += (on.empty() ? "" : ",") + k;
        else offList += (offList.empty() ? "" : ",") + k; // listed switched off: Apex shows it, ReShade does not run it
        sorting += (sorting.empty() ? "" : ",") + k;
        listed.insert(Lower(k));
    }
    for (const std::string& s : Looks::PresetSorting(g.ini))
        if (listed.insert(Lower(s)).second) sorting += (sorting.empty() ? "" : ",") + s;
    setLine(top, "Techniques", on);
    setLine(top, "TechniqueSorting", sorting);
    // any earlier ApexOff line (also a hand-edited "apexoff = ...") goes; the current one is written last
    top.erase(std::remove_if(top.begin(), top.end(), [](const std::string& l) {
        const size_t eq = l.find('=');
        if (eq == std::string::npos) return false;
        std::string k = l.substr(0, eq);
        while (!k.empty() && (k.back() == ' ' || k.back() == '\t')) k.pop_back();
        while (!k.empty() && (k.front() == ' ' || k.front() == '\t')) k.erase(0, 1);
        return _stricmp(k.c_str(), "ApexOff") == 0;
    }), top.end());
    if (!offList.empty()) top.push_back("ApexOff=" + offList);
    for (size_t i = 0; i < g.order.size(); ++i)
    {
        if (!Runnable(i) || IsRemoved(i)) continue;
        const auto& e = g.order[i];
        // a stand-in reads its values and definitions from its own file's section (RebuildOrder, DefinesFor): written there
        const std::string& file = e.alt.empty() ? e.file : e.alt;
        auto sec = std::find_if(secs.begin(), secs.end(), [&](const auto& s) { return _stricmp(s.first.c_str(), file.c_str()) == 0; });
        if (sec == secs.end())
        {
            auto at = std::find_if(secs.begin(), secs.end(), [&](const auto& s) { return _stricmp(s.first.c_str(), file.c_str()) > 0; });
            sec = secs.insert(at, { file, {} });
        }
        if (g.defs.count(Lower(file))) // ReShade 6 keeps an effect's own definitions in its section
        {
            std::string own;
            for (const auto& [k, lines] : g.ini.sections)
                if (_stricmp(k.c_str(), file.c_str()) == 0)
                    if (auto it = lines.find("PreprocessorDefinitions"); it != lines.end()) own = it->second;
            LooksDefines d = Looks::ParseDefines(own);
            for (const auto& [name, value] : g.defs[Lower(file)])
            {
                auto at = std::find_if(d.begin(), d.end(), [&](const auto& x) { return x.first == name; });
                if (at != d.end()) at->second = value;
                else d.push_back({ name, value });
            }
            setLine(sec->second, "PreprocessorDefinitions", Looks::FormatDefines(d));
        }
        const LooksShader& d = Looks::Shader(e.shader);
        const float* v = ValuesFor(i);
        for (int p = 0; p < d.paramCount; ++p)
        {
            const LooksParam& pd = d.params[p];
            if (pd.kind == LooksParamKind::Source) continue;
            setLine(sec->second, pd.key, Looks::FormatValue(pd, v + p * 4));
        }
    }
    std::string out;
    for (const auto& l : top) out += l + nl;
    for (const auto& [n, lines] : secs)
    {
        out += nl + "[" + n + "]" + nl;
        for (const auto& l : lines) out += l + nl;
    }
    return out;
}

// The file name a typed look name is saved under ("" when it cannot be one)
std::string LookFileName(std::string name)
{
    while (!name.empty() && name.back() == ' ') name.pop_back();
    while (!name.empty() && name.front() == ' ') name.erase(0, 1);
    if (name.size() > 4 && _stricmp(name.c_str() + name.size() - 4, ".ini") == 0) name.resize(name.size() - 4);
    return Looks::ValidLookFileName(name + ".ini") ? name + ".ini" : std::string();
}

bool SaveAsNewLook(const std::string& name, std::string& error)
{
    const std::string file = LookFileName(name);
    if (file.empty()) { error = I18n::Tr("Use letters, digits and spaces for the name"); return false; }
    if (!Looks::EnsureLooksFolder()) { error = I18n::Tr("The Looks folder could not be created"); return false; }
    std::string why;
    bool read = false;
    const std::string text = LookAsText(&read);
    if (!read) { error = I18n::Trf("Could not save {}", file); LOG_ERROR("[Looks] saving " + file + " refused: " + g.preset + " could not be read"); return false; }
    if (!ApexUtil::WriteFileAtomic(Looks::LooksFolder() + ApexUtil::ToWide(file), text, &why))
    {
        LOG_ERROR("[Looks] saving " + file + " failed: " + why);
        error = I18n::Trf("Could not save {}", file);
        return false;
    }
    LOG_INFO("[Looks] saved the look as Looks\\" + file);
    SelectLook("looks:" + file); // the new file holds everything: selected with no changes on top
    return true;
}

// "Save to this look": a look of the Looks folder is written over (the previous file kept as <name>.ini.bak); Apex
// writes nowhere else, so a GShade look is saved in the Looks folder under its own name and chosen there (My
// looks). When a look of that name is already there, nothing is written the first time: the error says saving replaces
// it, and the same Save again (replace = true, for the same look) does.
std::string g_replaceArmed; // the look whose Save already warned that it replaces a look in My looks
bool SaveToLook(std::string& error)
{
    if (g.preset.empty() || !g.loaded) { error = I18n::Tr("Choose a look first"); return false; }
    if (Looks::RefSource(g.preset) != Looks::Source::Mine)
    {
        std::string name = Looks::RefName(g.preset);
        if (const size_t slash = name.find_last_of("\\/"); slash != std::string::npos) name.erase(0, slash + 1);
        const std::string file = LookFileName(name);
        if (!file.empty() && ApexUtil::FileExists(Looks::LooksFolder() + ApexUtil::ToWide(file)) && g_replaceArmed != g.preset)
        {
            g_replaceArmed = g.preset; // the next Save of this look replaces it
            error = I18n::Tr("A look with this name exists; saving replaces it");
            return false;
        }
        g_replaceArmed.clear();
        return SaveAsNewLook(name, error);
    }
    const std::wstring path = Looks::RefPath(g.preset);
    std::string why;
    bool read = false;
    const std::string text = LookAsText(&read);
    if (!read) { error = I18n::Trf("Could not save {}", Looks::RefName(g.preset)); LOG_ERROR("[Looks] saving " + g.preset + " refused: it could not be read"); return false; }
    if (!path.empty()) CopyFileW(path.c_str(), (path + L".bak").c_str(), FALSE); // the file as it was, once per save
    if (path.empty() || !ApexUtil::WriteFileAtomic(path, text, &why))
    {
        LOG_ERROR("[Looks] saving " + g.preset + " failed: " + why);
        error = I18n::Trf("Could not save {}", Looks::RefName(g.preset));
        return false;
    }
    LOG_INFO("[Looks] saved the changes to " + g.preset);
    SelectLook(g.preset); // read back: the file now holds every change
    return true;
}

// ---------------------------------------------------------------------------------------------- shader packs
// look: an imported look's name, or an imported preset's (preset true; shaders is then 0, the preset names only packs)
struct ImportOffer { std::string look; int shaders = 0; std::vector<std::string> packs; bool preset = false; };
std::optional<ImportOffer> g_offer; // the note card after an import: packs that have shaders the look misses

// A web page in the browser, off the render thread (ShellExecuteW pumps the game window's messages)
void OpenPage(const std::string& url)
{
    HookGuard::StartDetached("Looks: open a pack's page", [url = ApexUtil::ToWide(url)] {
        const HRESULT com = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED | COINIT_DISABLE_OLE1DDE);
        ShellExecuteW(nullptr, L"open", url.c_str(), nullptr, nullptr, SW_SHOWNORMAL);
        if (SUCCEEDED(com)) CoUninitialize();
    });
}

// The pack that would bring run-list entry i (a missing .fx), when one on ReShade's list has it and is not downloaded yet
const Looks::Packs::Pack* PackFor(size_t i)
{
    const auto& e = g.order[i];
    if (Runnable(i) || Looks::Fx::HasFile(e.file) || (!e.alt.empty() && Looks::Fx::HasFile(e.alt))) return nullptr;
    const Looks::Packs::Pack* p = Looks::Packs::PackForFile(e.alt.empty() ? e.file : e.alt, e.technique);
    return p && !Looks::Packs::Downloaded(p->folder) ? p : nullptr;
}

// Packs that would bring the look's missing shaders, and how many shaders they bring
std::vector<std::string> MissingPacks(int* shaders = nullptr)
{
    std::vector<std::string> packs;
    int n = 0;
    for (size_t i = 0; i < g.order.size(); ++i)
        if (const Looks::Packs::Pack* p = PackFor(i))
        {
            ++n;
            if (std::find(packs.begin(), packs.end(), p->folder) == packs.end()) packs.push_back(p->folder);
        }
    if (shaders) *shaders = n;
    return packs;
}

std::string PackName(const std::string& folder)
{
    const Looks::Packs::Pack* p = Looks::Packs::Find(folder);
    return p ? p->name : folder;
}

// "qUINT", "qUINT and AstrayFX", "3 packs"
std::string PackNames(const std::vector<std::string>& folders)
{
    if (folders.size() == 1) return PackName(folders[0]);
    if (folders.size() == 2) return I18n::Trf("{} and {}", PackName(folders[0]), PackName(folders[1]));
    return I18n::Trf("{} packs", folders.size());
}

// "Download <pack>", "Download both", "Download all"
std::string DownloadLabel(const std::vector<std::string>& folders)
{
    if (folders.size() == 1) return I18n::Trf("Download {}", PackName(folders[0]));
    return I18n::Tr(folders.size() == 2 ? "Download both" : "Download all");
}

std::string SizeText(uint32_t kb)
{
    if (kb < 1024) return I18n::Trf("{} KB", std::max<uint32_t>(1, kb));
    std::string s = I18n::Trf("{:.1f} MB", kb / 1024.0);
    ApexUi::LocaleDecimal(s.data()); // "56,3 MB" where the language writes a comma
    return s;
}

// Starts downloads; the player stays where they are (the download bar and the rows that wait show the progress)
void DownloadPacks(const std::vector<std::string>& folders)
{
    Looks::Packs::Download(folders); // the player stays where they are: the rows that wait show the progress
}

