// The native file picker for the Import button, off the render thread (it pumps the game window's messages)
void PickPreset()
{
    if (g_pickBusy.exchange(true)) return;
    std::wstring label = ApexUtil::ToWide(I18n::Tr("ReShade presets"));
    if (!HookGuard::StartDetached("Looks: import a preset", [label = std::move(label)] {
        std::optional<std::wstring> picked;
        struct Finish
        {
            std::optional<std::wstring>& picked;
            ~Finish() { std::lock_guard<std::mutex> lock(g_pickLock); g_picked = std::move(picked); g_pickBusy = false; }
        } finish{ picked };
        const HRESULT com = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
        if (FAILED(com)) return;
        IFileDialog* dialog = nullptr;
        if (SUCCEEDED(CoCreateInstance(CLSID_FileOpenDialog, nullptr, CLSCTX_INPROC_SERVER, IID_PPV_ARGS(&dialog))))
        {
            const COMDLG_FILTERSPEC types[] = { { label.c_str(), L"*.ini" } };
            dialog->SetFileTypes(1, types);
            DWORD options = 0;
            dialog->GetOptions(&options);
            dialog->SetOptions(options | FOS_FORCEFILESYSTEM | FOS_NOCHANGEDIR | FOS_FILEMUSTEXIST);
            if (SUCCEEDED(dialog->Show(nullptr)))
            {
                IShellItem* item = nullptr;
                if (SUCCEEDED(dialog->GetResult(&item)))
                {
                    PWSTR path = nullptr;
                    if (SUCCEEDED(item->GetDisplayName(SIGDN_FILESYSPATH, &path))) { picked = path; CoTaskMemFree(path); }
                    item->Release();
                }
            }
            dialog->Release();
        }
        CoUninitialize();
    })) g_pickBusy = false;
}

// Copies the picked .ini into Looks\ (a numbered name on a clash with another file; the same file is reused) and selects it
bool ImportPicked(const std::wstring& path)
{
    auto fail = [](const std::string& text) { g_message = text; g_messageError = true; return false; };
    std::string bytes;
    WIN32_FILE_ATTRIBUTE_DATA info{};
    if (!GetFileAttributesExW(path.c_str(), GetFileExInfoStandard, &info) || info.nFileSizeHigh || info.nFileSizeLow > Looks::kMaxPresetBytes ||
        !ApexUtil::ReadFileBytes(path, bytes) || bytes.size() > Looks::kMaxPresetBytes)
        return fail(I18n::Tr("This file can't be read as a preset"));
    Looks::Preset probe;
    Looks::ParsePreset(bytes, probe);
    const auto top = probe.sections.find("");
    if (top == probe.sections.end() || (!top->second.count("Techniques") && !top->second.count("TechniqueSorting")))
        return fail(I18n::Tr("This file is not a ReShade preset"));
    std::string name = ApexUtil::ToUtf8(path.substr(path.find_last_of(L"\\/") + 1));
    if (!Looks::ValidLookFileName(name)) name = "Imported look.ini";
    std::string stored, why;
    if (!Looks::StoreLook(name, bytes, stored, nullptr, &why))
    {
        LOG_ERROR("[Looks] import failed: " + why);
        return fail(I18n::Tr("The preset could not be copied to the Looks folder"));
    }
    LOG_INFO("[Looks] imported " + ApexUtil::ToUtf8(path) + " as Looks\\" + stored);
    SelectLook("looks:" + stored);
    g_message = I18n::Trf("Imported as {}", Looks::RefName("looks:" + stored));
    g_messageError = false;
    ImportOffer offer;
    offer.look = Looks::RefName("looks:" + stored);
    offer.packs = MissingPacks(&offer.shaders);
    if (!offer.packs.empty()) g_offer = std::move(offer); else g_offer.reset();
    return true;
}

