bool IEqual(const std::string& a, const std::string& b) { return _stricmp(a.c_str(), b.c_str()) == 0; }

// One of the player's .fx files (a path the scan found) to the Recycle Bin, nothing else, off the render thread; then a
// scan. Only a regular .fx file inside the Shaders folder; the result goes to g_recycled (FxMessages shows it).
void RecycleFx(const std::wstring& path)
{
    HookGuard::StartDetached("Looks: move a .fx file to the Recycle Bin", [path] {
        const std::wstring root = Looks::Fx::ShadersFolder();
        const DWORD attr = GetFileAttributesW(path.c_str());
        const bool safe = !root.empty() && path.size() > root.size() + 3 && _wcsnicmp(path.c_str(), root.c_str(), root.size()) == 0 &&
                          path.find(L"..") == std::wstring::npos && _wcsicmp(path.c_str() + path.size() - 3, L".fx") == 0 &&
                          attr != INVALID_FILE_ATTRIBUTES && !(attr & (FILE_ATTRIBUTE_DIRECTORY | FILE_ATTRIBUTE_REPARSE_POINT));
        bool ok = false;
        if (safe)
        {
            const std::wstring from = path + L'\0'; // pFrom ends with two nulls
            const HRESULT com = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED | COINIT_DISABLE_OLE1DDE);
            SHFILEOPSTRUCTW op{};
            op.wFunc = FO_DELETE;
            op.pFrom = from.c_str();
            // no Recycle Bin on that drive: Windows asks before deleting for good (No keeps the file)
            op.fFlags = FOF_ALLOWUNDO | FOF_WANTNUKEWARNING | FOF_NOCONFIRMATION | FOF_SILENT | FOF_NOERRORUI;
            ok = SHFileOperationW(&op) == 0 && !op.fAnyOperationsAborted;
            if (SUCCEEDED(com)) CoUninitialize();
        }
        {
            std::lock_guard<std::mutex> lock(g_addLock);
            g_recycled.emplace(ApexUtil::ToUtf8(path.substr(path.find_last_of(L'\\') + 1)), ok);
        }
        Looks::Fx::RequestScan(false); // the file leaves the list; the other files stay compiled
    });
}

// "Add .fx files…": the native picker (several files), then the copy into the Shaders folder, all off the render thread
void PickFxFiles()
{
    if (g_addBusy.exchange(true)) return;
    std::wstring label = ApexUtil::ToWide(I18n::Tr("ReShade shaders and textures"));
    if (!HookGuard::StartDetached("Looks: add .fx files", [label = std::move(label)] {
        std::vector<std::wstring> picked;
        struct Finish
        {
            std::vector<std::wstring>& picked;
            ~Finish()
            {
                std::optional<Looks::Fx::AddResult> r;
                if (!picked.empty()) r = Looks::Fx::AddFiles(picked);
                std::lock_guard<std::mutex> lock(g_addLock);
                g_added = r;
                g_addBusy = false;
            }
        } finish{ picked };
        const HRESULT com = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
        if (FAILED(com)) return;
        IFileOpenDialog* dialog = nullptr;
        if (SUCCEEDED(CoCreateInstance(CLSID_FileOpenDialog, nullptr, CLSCTX_INPROC_SERVER, IID_PPV_ARGS(&dialog))))
        {
            const COMDLG_FILTERSPEC types[] = { { label.c_str(), L"*.fx;*.fxh;*.png;*.jpg;*.jpeg;*.bmp;*.dds" } };
            dialog->SetFileTypes(1, types);
            DWORD options = 0;
            dialog->GetOptions(&options);
            dialog->SetOptions(options | FOS_FORCEFILESYSTEM | FOS_NOCHANGEDIR | FOS_FILEMUSTEXIST | FOS_ALLOWMULTISELECT);
            if (SUCCEEDED(dialog->Show(nullptr)))
            {
                IShellItemArray* items = nullptr;
                if (SUCCEEDED(dialog->GetResults(&items)))
                {
                    DWORD n = 0;
                    items->GetCount(&n);
                    for (DWORD k = 0; k < n && k < 500; ++k)
                    {
                        IShellItem* item = nullptr;
                        PWSTR path = nullptr;
                        if (SUCCEEDED(items->GetItemAt(k, &item)) && SUCCEEDED(item->GetDisplayName(SIGDN_FILESYSPATH, &path))) { picked.push_back(path); CoTaskMemFree(path); }
                        if (item) item->Release();
                    }
                    items->Release();
                }
            }
            dialog->Release();
        }
        CoUninitialize();
    })) g_addBusy = false;
}

// Menu frame: the result of an "Add .fx files…" copy, and of a "Check again" scan, as one translated line
void FxMessages(int missingFiles)
{
    std::optional<Looks::Fx::AddResult> added;
    std::optional<std::pair<std::string, bool>> recycled;
    {
        std::lock_guard<std::mutex> lock(g_addLock);
        added.swap(g_added);
        recycled.swap(g_recycled);
    }
    if (recycled)
    {
        g_fxMessagePacks = false;
        g_fxMessageError = !recycled->second;
        g_fxMessage = recycled->second ? I18n::Trf("{} moved to the Recycle Bin", recycled->first) : I18n::Trf("{} could not be moved to the Recycle Bin", recycled->first);
    }
    if (added)
    {
        g_fxMessagePacks = false;
        const int copied = added->added + added->reused;
        g_fxMessageError = added->refused > 0;
        g_fxMessage = added->refused ? I18n::Trf("{} files added; {} refused (only .fx, .fxh and images)", copied, added->refused)
                      : copied == 1  ? std::string(I18n::Tr("1 file added"))
                                     : I18n::Trf("{} files added", copied);
        g_checkPending = true;
    }
    if (g_checkPending && !g.active) // nothing is checked while Shaders is off
    {
        g_checkPending = false;
        g_fxMessage = I18n::Tr("Turn on Shaders to check what changed");
        g_fxMessageError = false;
    }
    if (g_checkPending && !Looks::Fx::Scanning())
    {
        g_checkPending = false;
        if (!added && missingFiles == 0) { g_fxMessage = I18n::Tr("All shaders found"); g_fxMessageError = false; }
        else if (!added && missingFiles > 0) { g_fxMessage = I18n::Trf("{} still missing", missingFiles); g_fxMessageError = true; }
    }
}

// ---------------------------------------------------------------------------------------------- menu: wrapping controls
// The lines a group of controls takes at `avail` (widths in order, `gap` apart), wrapping as SameLineIfFits does
int WrapLines(std::initializer_list<float> widths, float avail, float gap)
{
    int lines = 1;
    float x = -gap;
    for (float w : widths)
    {
        if (x > 0.0f && x + gap + w > avail + 1.0f) { ++lines; x = w; }
        else x += gap + w;
    }
    return lines;
}

// Before the next control of such a group: on the same line when it still ends before `right` (screen x), else on the next
void SameLineIfFits(float w, float gap, float right)
{
    if (ImGui::GetItemRectMax().x + gap + w <= right + 1.0f) ImGui::SameLine(0.0f, gap); // 1 px: rounding of measured widths
}

